function normalizeStore(raw = {}) {
  const base = seed;
  raw = raw || {};
  return {
    ...base,
    ...raw,
    products: (!Array.isArray(raw.products) || raw.products.length<100 || raw.products.some(p=>String(p.id||'').startsWith('imp-cr-')) || raw.settings?.inventorySeedVersion!=='2026-08-28-inventory-v2') ? initialInventory : raw.products.filter(p=>p.category!=='Cristales'),
    crystalCatalog: Array.isArray(raw.crystalCatalog) && raw.crystalCatalog.length ? raw.crystalCatalog : initialCrystalCatalog,
    customers: Array.isArray(raw.customers) ? raw.customers : [],
    laboratories: Array.isArray(raw.laboratories) && raw.laboratories.length ? raw.laboratories : base.laboratories,
    sales: Array.isArray(raw.sales) ? raw.sales : [],
    orders: Array.isArray(raw.orders) ? raw.orders : [],
    expenses: Array.isArray(raw.expenses) ? raw.expenses : [],
    payments: Array.isArray(raw.payments) ? raw.payments : [],
    inventoryMovements: Array.isArray(raw.inventoryMovements) ? raw.inventoryMovements : [],
    cashHistory: Array.isArray(raw.cashHistory) ? raw.cashHistory : [],
    cash: { ...base.cash, ...(raw.cash || {}) },
    settings: { ...base.settings, ...(raw.settings || {}) }
  };
}
function loadStore(){
  try {
    const raw = localStorage.getItem('gafascity-store-v2');
    return normalizeStore(raw ? JSON.parse(raw) : seed);
  } catch (error) {
    console.error('Error cargando datos locales', error);
    return normalizeStore(seed);
  }
}
class ErrorBoundary extends React.Component {
  constructor(props){super(props);this.state={error:null};}
  static getDerivedStateFromError(error){return {error};}
  componentDidCatch(error, info){console.error(error, info);}
  render(){
    if(this.state.error){return <div className="appError"><h2>Ocurrio un error controlado</h2><p>{String(this.state.error?.message || this.state.error)}</p><button onClick={()=>{localStorage.removeItem('gafascity-store-v2');location.reload();}}>Limpiar datos locales y recargar</button></div>;}
    return this.props.children;
  }
}
