    ...sales.filter(s=>!s.cancelled&&saleBalance(s)>0).map(s=>({id:`sale:${s.id}`,source:'Venta',sourceId:s.id,number:s.number||s.id,customer:s.customerName||'',idCard:s.idCard||'',phone:s.phone||'',total:Number(s.total||0),paid:salePaid(s),balance:saleBalance(s),date:s.date||'',description:s.productCodeName||s.description||'Venta',raw:s})),
    ...orders.filter(o=>Number(o.balance||0)>0).map(o=>({id:`order:${o.id}`,source:'Trabajo optico',sourceId:o.id,number:o.number||o.id,customer:o.customer||'',idCard:o.idCard||'',phone:o.phone||'',total:Number(o.total||0),paid:Math.max(0,Number(o.total||0)-Number(o.balance||0)),balance:Number(o.balance||0),date:o.date||'',description:`Trabajo optico ${o.number||''}`,raw:o}))
